using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Diagnostics;

using Microsoft.Xna.Framework;
using System.Diagnostics;

namespace CursedUIUser
{

  public partial class ClassMapping : Experiment
  {
    /// <summary>
    /// can this be autogenerated?DDD
    /// </summary>
    public class MagicMirror
    {

      // original classes
      public class Canvas
      {
        public void DrawTexture(Texture texture) { }
      }

      public class Texture { }

      // Internal wrappers
      public static class Mirror
      {
        public static Func<FCanvas, Canvas> CanvasReflection;
        public static Func<FTexture, Texture> TextureReflection;

        public static Canvas TakeALook(FCanvas canvas) => CanvasReflection(canvas);
        public static Texture TakeALook(FTexture texture) => TextureReflection(texture);
      }

      public class FCanvas(Canvas self)
      {
        private Canvas Self = self;
        static FCanvas() { Mirror.CanvasReflection = (fake) => fake.Self; }

        public void DrawTexture(FTexture texture) => Self.DrawTexture(Mirror.TakeALook(texture));
      }

      public class FTexture(Texture self)
      {
        private Texture Self = self;
        static FTexture() { Mirror.TextureReflection = (fake) => fake.Self; }
      }



    }

  }


}